from itertools import combinations, chain
from app.services.rules.distance import PairDistanceRule
kinds=['a','b','c']
def subsets(s):
    return chain.from_iterable(combinations(s,r) for r in range(len(s)+1))
bad=0; checked=0
for p in subsets(kinds):
    for s in subsets(kinds):
        r=PairDistanceRule('X',set(p),set(s),5.0)
        for ck in kinds:
            counterpart=set()
            if ck in r.primary_kinds: counterpart |= r.secondary_kinds
            if ck in r.secondary_kinds: counterpart |= r.primary_kinds
            for ok in kinds:
                checked+=1
                fast = ok in counterpart
                slow = r._applies(ck, ok)
                if fast != slow:
                    bad+=1; print('MISMATCH',p,s,ck,ok,fast,slow)
